create table issues (created_time timestamp(6), detected_at timestamp(6), last_updated_time timestamp(6), resolved_at timestamp(6), sla_due_at timestamp(6), priority varchar(10) not null check (priority in ('P1','P2','P3','P4')), assignee_id uuid, id uuid not null, tenant_id uuid, category varchar(20) not null check (category in ('OUTAGE','BUG','PERFORMANCE','DATA','SECURITY','CONFIG','OTHER')), environment varchar(20) not null check (environment in ('PRODUCTION','STAGING','DR')), issue_key varchar(20) not null unique, resolution varchar(20) check (resolution in ('FIXED','WONT_FIX','DUPLICATE','CANNOT_REPRODUCE','CONFIG_CHANGE')), severity varchar(20) not null check (severity in ('S1_CRITICAL','S2_HIGH','S3_MEDIUM','S4_LOW')), status varchar(20) not null check (status in ('NEW','TRIAGED','IN_PROGRESS','AWAITING_TENANT','RESOLVED','CLOSED','REOPENED')), affected_service varchar(120), assignee_name varchar(255), created_by varchar(255), description varchar(255), last_updated_by varchar(255), reported_by varchar(255), summary varchar(255) not null, tenant_name varchar(255), primary key (id));
create table tenant_environments (created_time timestamp(6), last_updated_time timestamp(6), id uuid not null, tenant_id uuid not null, environment varchar(20) not null check (environment in ('PRODUCTION','STAGING','DR')), region varchar(40), base_url varchar(255), created_by varchar(255), health_check_url varchar(255), last_updated_by varchar(255), primary key (id));
create table tenants (created_time timestamp(6), last_updated_time timestamp(6), id uuid not null, status varchar(20) not null check (status in ('ONBOARDING','ACTIVE','SUSPENDED','OFFBOARDED')), support_tier varchar(20) not null check (support_tier in ('BASIC','STANDARD','PREMIUM','ENTERPRISE')), region varchar(40), tenant_code varchar(40) not null unique, name varchar(160) not null, primary_contact_email varchar(160), primary_contact_name varchar(160), created_by varchar(255), last_updated_by varchar(255), production_url varchar(255), primary key (id));
create table users (active boolean not null, created_time timestamp(6), last_updated_time timestamp(6), id uuid not null, tenant_id uuid not null, role varchar(20) not null check (role in ('ADMIN','ENGINEER','SUPPORT','VIEWER')), email varchar(160) not null unique, full_name varchar(160) not null, created_by varchar(255), last_updated_by varchar(255), tenant_name varchar(255), primary key (id));
